package in.lmt.commercial;
import in.lmt.shared.*;
import in.lmt.identity.*;
import in.lmt.workspace.WorkspaceCommands;
import java.util.*;
import java.time.*;
import java.math.*;
import java.util.function.Supplier;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import tools.jackson.databind.ObjectMapper;
@Service @Transactional
public class SubscriptionUpgrades {
 private final JdbcClient db;private final WorkspaceCommands scope;private final IdentityConfig config;private final Audit audit;private final ObjectMapper json;private final Entitlements entitlements;
 public SubscriptionUpgrades(JdbcClient db,WorkspaceCommands scope,IdentityConfig config,Audit audit,ObjectMapper json,Entitlements entitlements){this.db=db;this.scope=scope;this.config=config;this.audit=audit;this.json=json;this.entitlements=entitlements;}
 public record Offer(UUID id,UUID targetVersionId,String name,int rentableLimit,int managerLimit,String baseAmount,String taxRate,int intervalMonths,String proration,String recipient,String disclosure){}
 public record State(UUID workspaceId,String currentPlan,int subscriptionVersion,String etag,List<Offer> offers,List<Change> changes,String mode,String explanation){}
 public record Quote(UUID id,UUID offerId,UUID targetVersionId,int subscriptionVersion,int policyVersion,String entitlementFingerprint,String currentPlan,String requestedPlan,int rentableLimit,int managerLimit,List<String> newFeatures,String baseAmount,String credit,String taxableAmount,String taxRate,String tax,String total,String currency,int intervalMonths,String proration,String recipient,String effectivePolicy,Instant quotedAt,Instant expiresAt,String mode){}
 public record Retry(String policyVersion,Integer attemptNumber,Integer maxAttempts,Instant failedAt,Instant retryAt,boolean allowed,String reason,String graceStatus,String restrictions){}
 public record Change(UUID id,String status,int version,String etag,Quote quote,Instant appliedAt,Retry retry,SettlementView settlement){}
 public record Recovery(UUID workspaceId,String mode,String currentPlan,String subscriptionStatus,String workspaceStatus,String graceStatus,Instant graceEndsAt,String graceExplanation,String restrictions,List<Change> changes,Instant asOf){}
 private Instant now(){return db.sql("SELECT clock_timestamp()").query(java.time.OffsetDateTime.class).single().toInstant();}
 private String tag(UUID w,int v){return "\"subscription-"+w+"-v"+v+"\"";}
 private String ctag(UUID id,int v){return "\"upgrade-"+id+"-v"+v+"\"";}
 private void match(String tag,String actual){if(tag==null||tag.isBlank())throw new ApiProblem(428,"PRECONDITION_REQUIRED","Refresh the subscription and review its current version.");if(!tag.equals(actual))throw new ApiProblem(412,"VERSION_STALE","The subscription or change was updated. Refresh before confirming.");}
 private Map<String,Object> subscription(UUID w){return db.sql("SELECT s.*,p.display_name FROM workspace_subscription s JOIN plan_version p ON p.version_id=s.plan_version_id WHERE workspace_id=:w").param("w",w).query().singleRow();}
 private void sandbox(UUID w){if(!config.sandbox||!db.sql("SELECT mode='sandbox' FROM workspace WHERE id=:w").param("w",w).query(Boolean.class).single())throw new ApiProblem(409,"PAYMENT_PROVIDER_UNAVAILABLE","Live subscription checkout is not configured. Sandbox payment outcomes cannot be used here.");}
 private void active(UUID w){if(db.sql("SELECT count(*) FROM subscription_settlement WHERE workspace_id=:w AND status='reversal_review'").param("w",w).query(Long.class).single()>0)throw new ApiProblem(409,"PAYMENT_REVERSAL_REVIEW_REQUIRED","Resolve the recorded payment reversal before another discretionary subscription change.");if(db.sql("SELECT count(*) FROM subscription_downgrade_request WHERE workspace_id=:w AND status IN('scheduled','review_required')").param("w",w).query(Long.class).single()>0)throw new ApiProblem(409,"DOWNGRADE_PENDING","Cancel the pending downgrade before an upgrade or simulated payment.");if(!db.sql("SELECT status='active' FROM workspace WHERE id=:w").param("w",w).query(Boolean.class).single())throw new ApiProblem(409,"WORKSPACE_RESTRICTED","Resolve workspace restrictions before requesting a discretionary upgrade.");}
 private String fingerprint(UUID w,UUID target){return ChallengeService.hash(json.writeValueAsString(entitlements.preview(w,target)));}
 private int policy(){return db.sql("SELECT version FROM commercial_policy WHERE effective_at<=CURRENT_TIMESTAMP ORDER BY effective_at DESC,version DESC LIMIT 1").query(Integer.class).single();}
 List<Offer> offers(UUID w){return db.sql("""
 SELECT o.*,p.display_name,p.rentable_limit,p.manager_limit FROM subscription_upgrade_offer o JOIN plan_version p ON p.version_id=o.target_plan_id JOIN workspace_subscription s ON s.plan_version_id=o.source_plan_id
 WHERE s.workspace_id=:w AND p.audience='workspace' AND p.publication_state='published' AND p.effective_at<=CURRENT_TIMESTAMP
 AND NOT EXISTS(SELECT 1 FROM subscription_upgrade_offer_withdrawal x WHERE x.offer_id=o.id)
 AND NOT EXISTS(SELECT 1 FROM plan_offering_availability a WHERE a.audience=p.audience AND a.code=p.code AND NOT a.available)
 ORDER BY p.rentable_limit,o.created_at,o.id LIMIT 100
 """).param("w",w).query((r,n)->new Offer(r.getObject("id",UUID.class),r.getObject("target_plan_id",UUID.class),r.getString("display_name"),r.getInt("rentable_limit"),r.getInt("manager_limit"),r.getBigDecimal("base_amount").toPlainString(),r.getBigDecimal("tax_rate").toPlainString(),r.getInt("interval_months"),r.getString("proration"),r.getString("recipient"),r.getString("disclosure"))).list();}
 public State state(UUID actor,UUID w){scope.requireOwner(w,actor);var s=subscription(w);boolean local=config.sandbox&&db.sql("SELECT mode='sandbox' FROM workspace WHERE id=:w").param("w",w).query(Boolean.class).single();var ids=db.sql("SELECT id FROM subscription_upgrade_change WHERE workspace_id=:w ORDER BY created_at DESC,id DESC LIMIT 25").param("w",w).query(UUID.class).list();return new State(w,(String)s.get("display_name"),(Integer)s.get("version"),tag(w,(Integer)s.get("version")),local?offers(w):List.of(),ids.stream().map(id->change(w,id)).toList(),local?"sandbox":"unavailable",local?"Local payment simulation only. No money is collected. Only explicitly configured test offers can be quoted. Most recent 25 changes shown.":"Live pricing and provider checkout are not configured.");}
 private Quote quote(UUID w,UUID id){return db.sql("SELECT snapshot::text FROM subscription_upgrade_quote WHERE workspace_id=:w AND id=:id").param("w",w).param("id",id).query(String.class).optional().map(s->json.readValue(s,Quote.class)).orElseThrow(()->new ApiProblem(404,"QUOTE_NOT_FOUND","Quote is unavailable."));}
 private Change change(UUID w,UUID id){var r=db.sql("SELECT * FROM subscription_upgrade_change WHERE workspace_id=:w AND id=:id").param("w",w).param("id",id).query().listOfRows().stream().findFirst().orElseThrow(()->new ApiProblem(404,"CHANGE_NOT_FOUND","Upgrade change is unavailable."));int v=(Integer)r.get("version");return new Change(id,(String)r.get("status"),v,ctag(id,v),quote(w,(UUID)r.get("quote_id")),r.get("applied_at")==null?null:((java.sql.Timestamp)r.get("applied_at")).toInstant(),retry(w,r),settlement(w,id));}
 private SettlementView settlement(UUID w,UUID id){return db.sql("SELECT * FROM subscription_settlement WHERE workspace_id=:w AND id=:id").param("w",w).param("id",id).query((r,n)->new SettlementView(id,r.getString("status"),r.getInt("version"),"\"settlement-"+id+"-v"+r.getInt("version")+"\"",r.getTimestamp("received_at").toInstant(),r.getTimestamp("applied_at")==null?null:r.getTimestamp("applied_at").toInstant(),r.getTimestamp("reversed_at")==null?null:r.getTimestamp("reversed_at").toInstant(),r.getInt("attempts"),r.getString("last_code"))).optional().orElse(null);}
 private Retry retry(UUID w,Map<String,Object> r){
  String policy=(String)r.get("retry_policy");var failed=r.get("failed_at")==null?null:((java.sql.Timestamp)r.get("failed_at")).toInstant();
  if(policy==null)return new Retry(null,null,null,failed,null,false,"LEGACY_POLICY_REVIEW_REQUIRED","not_applicable","Failed upgrades do not restrict the existing subscription. Legacy retry policy/history is unavailable; review a fresh quote after a definitive failure.");
  var p=db.sql("SELECT * FROM subscription_retry_policy WHERE version=:p").param("p",policy).query().singleRow();int attempt=(Integer)r.get("attempt_number"),max=(Integer)p.get("max_attempts");Instant retryAt=failed==null?null:failed.plusSeconds((Integer)p.get("cooldown_seconds"));String reason="RETRY_AVAILABLE";
  var q=quote(w,(UUID)r.get("quote_id"));var sub=subscription(w);var workspace=db.sql("SELECT mode,status FROM workspace WHERE id=:w").param("w",w).query().singleRow();
  if(!config.sandbox||!workspace.get("mode").equals("sandbox"))reason="PAYMENT_PROVIDER_UNAVAILABLE";
  else if(!workspace.get("status").equals("active"))reason="WORKSPACE_RESTRICTED";
  else if(!r.get("status").equals("payment_failed"))reason=r.get("status").equals("payment_unknown")?"PROVIDER_OUTCOME_UNKNOWN":"RETRY_NOT_REQUIRED";
  else if(!now().isBefore(q.expiresAt())||(Integer)sub.get("version")!=q.subscriptionVersion())reason="APPROVAL_STALE";
  else if(policy()!=q.policyVersion()||!fingerprint(w,q.targetVersionId()).equals(q.entitlementFingerprint()))reason="APPROVAL_STALE";
  else if(offers(w).stream().noneMatch(o->o.id().equals(q.offerId())))reason="OFFER_UNAVAILABLE";
  else if(attempt>=max)reason="PAYMENT_RETRY_EXHAUSTED";
  else if(retryAt==null||now().isBefore(retryAt))reason="PAYMENT_RETRY_NOT_DUE";
  else if(db.sql("SELECT count(*) FROM subscription_upgrade_change WHERE workspace_id=:w AND id<>:id AND status IN('awaiting_payment','payment_unknown','review_required')").param("w",w).param("id",r.get("id")).query(Long.class).single()>0||db.sql("SELECT count(*) FROM subscription_downgrade_request WHERE workspace_id=:w AND status IN('scheduled','review_required')").param("w",w).query(Long.class).single()>0)reason="SUBSCRIPTION_CHANGE_PENDING";
  return new Retry(policy,attempt,max,failed,retryAt,reason.equals("RETRY_AVAILABLE"),reason,"not_applicable","Only the requested upgrade is withheld until verified settlement. Existing plan access and records are preserved; independent security/permission restrictions still apply.");
 }
 @Transactional(readOnly=true,isolation=org.springframework.transaction.annotation.Isolation.REPEATABLE_READ)
 public Recovery recovery(UUID actor,UUID w){scope.requireOwner(w,actor);var s=subscription(w);String ws=db.sql("SELECT status FROM workspace WHERE id=:w").param("w",w).query(String.class).single();var current=state(actor,w);return new Recovery(w,current.mode(),current.currentPlan(),(String)s.get("status"),ws,"not_applicable",null,"These are upgrade payments, not overdue renewal invoices. They do not start a grace countdown or reduce the existing plan. Renewal collection and its approved grace/restriction policy are not implemented.","A failed or unknown upgrade never grants new capacity. Existing subscription access is unchanged by these failures. Current workspace security status: "+ws+". No automatic collection or record deletion.",current.changes(),now());}
 public Change retryPayment(UUID actor,UUID w,UUID id,UUID key,String expected){return command(actor,w,"payment-retry:"+id,key,Collections.singletonList(expected),Change.class,()->{var c=change(w,id);match(expected,c.etag());var r=c.retry();if(!r.allowed())throw new ApiProblem(409,r.reason(),"Payment retry is unavailable. Refresh the recovery status; reconcile unknown outcomes or review fresh terms when required.");active(w);var q=c.quote();offered(w,q.offerId());if(policy()!=q.policyVersion()||!fingerprint(w,q.targetVersionId()).equals(q.entitlementFingerprint()))throw new ApiProblem(409,"APPROVAL_STALE","Policy changed. Review fresh payment terms.");capacity(w,offered(w,q.offerId()));db.sql("UPDATE subscription_upgrade_change SET status='awaiting_payment',version=version+1,attempt_number=attempt_number+1 WHERE id=:id").param("id",id).update();audit.record(actor,w,"subscription.payment_retry_requested",id);return change(w,id);});}
 public Change get(UUID actor,UUID w,UUID id){scope.requireOwner(w,actor);return change(w,id);}
 private <T>T command(UUID actor,UUID w,String operation,UUID key,Object body,Class<T> type,Supplier<T> run){scope.requireOwner(w,actor);db.sql("SELECT pg_advisory_xact_lock(hashtextextended(:key,0))").param("key","membership:"+w).query().singleRow();db.sql("SELECT id FROM workspace_subscription WHERE workspace_id=:w FOR UPDATE").param("w",w).query(UUID.class).single();scope.requireOwner(w,actor);sandbox(w);String hash=ChallengeService.hash(json.writeValueAsString(body));var previous=db.sql("SELECT request_hash,result::text FROM subscription_upgrade_command WHERE actor_id=:a AND workspace_id=:w AND operation=:o AND request_key=:k").param("a",actor).param("w",w).param("o",operation).param("k",key).query().listOfRows().stream().findFirst();if(previous.isPresent()){var p=previous.get();if(!hash.equals(p.get("request_hash")))throw new ApiProblem(409,"IDEMPOTENCY_CONFLICT","This confirmation key has different arguments.");return json.readValue((String)p.get("result"),type);}T result=run.get();db.sql("INSERT INTO subscription_upgrade_command(actor_id,workspace_id,operation,request_key,request_hash,result) VALUES(:a,:w,:o,:k,:h,CAST(:r AS jsonb))").param("a",actor).param("w",w).param("o",operation).param("k",key).param("h",hash).param("r",json.writeValueAsString(result)).update();return result;}
 private BigDecimal money(String n){return new BigDecimal(n).setScale(2,RoundingMode.HALF_UP);}
 private Offer offered(UUID w,UUID id){return offers(w).stream().filter(o->o.id().equals(id)).findFirst().orElseThrow(()->new ApiProblem(409,"OFFER_UNAVAILABLE","This configured upgrade offer is no longer available."));}
 private void capacity(UUID w,Offer o){var grants=db.sql("SELECT resource,allowance FROM workspace_grant WHERE workspace_id=:w ORDER BY resource FOR UPDATE").param("w",w).query().listOfRows();boolean increase=false;for(var g:grants){int old=((Number)g.get("allowance")).intValue(),target=g.get("resource").equals("managers")?o.managerLimit():o.rentableLimit();if(target<old)throw new ApiProblem(409,"NOT_AN_UPGRADE","The target cannot reduce an existing capacity allowance.");increase|=target>old;}if(!increase)throw new ApiProblem(409,"NOT_AN_UPGRADE","A higher configured capacity is required for this upgrade flow.");}
 public Quote createQuote(UUID actor,UUID w,UUID key,String expected,UUID offerId){return command(actor,w,"quote",key,Arrays.asList(expected,offerId),Quote.class,()->{active(w);var s=subscription(w);int version=(Integer)s.get("version");match(expected,tag(w,version));Offer o=offered(w,offerId);capacity(w,o);int policy=policy();
  if(db.sql("SELECT count(*) FROM commercial_plan_capability WHERE policy_version=:p AND plan_version_id=:v").param("p",policy).param("v",o.targetVersionId()).query(Long.class).single()==0)throw new ApiProblem(409,"ENTITLEMENT_CONFIGURATION_UNAVAILABLE","The target plan has no reviewed capability bindings.");
  if(db.sql("SELECT count(*) FROM commercial_plan_capability a WHERE a.policy_version=:p AND a.plan_version_id=:current AND NOT EXISTS(SELECT 1 FROM commercial_plan_capability b WHERE b.policy_version=a.policy_version AND b.plan_version_id=:target AND b.capability=a.capability)").param("p",policy).param("current",s.get("plan_version_id")).param("target",o.targetVersionId()).query(Long.class).single()>0)throw new ApiProblem(409,"NOT_AN_UPGRADE","The target would remove a contracted capability.");
  Instant now=now();BigDecimal base=money(o.baseAmount()),credit=BigDecimal.ZERO.setScale(2);
  if(s.get("status").equals("active_paid")){if(!o.proration().equals("unused_time_credit")||s.get("period_end")==null)throw new ApiProblem(409,"PRORATION_UNAVAILABLE","A reviewed paid-period credit rule is required.");Instant start=((java.sql.Timestamp)s.get("period_start")).toInstant(),end=((java.sql.Timestamp)s.get("period_end")).toInstant();if(!now.isBefore(end))throw new ApiProblem(409,"BILLING_PERIOD_EXPIRED","Resolve the expired billing period before an upgrade.");credit=((BigDecimal)s.get("base_amount")).multiply(BigDecimal.valueOf(Duration.between(now,end).toMillis())).divide(BigDecimal.valueOf(Duration.between(start,end).toMillis()),2,RoundingMode.HALF_UP);if(credit.compareTo(base)>0)throw new ApiProblem(409,"CREDIT_REVIEW_REQUIRED","Credit exceeds the target price and needs a separately approved credit policy.");}
  BigDecimal taxable=base.subtract(credit),tax=taxable.multiply(new BigDecimal(o.taxRate())).divide(new BigDecimal("100"),2,RoundingMode.HALF_UP);
  if(taxable.add(tax).compareTo(new BigDecimal("999999999999.99"))>0)throw new ApiProblem(409,"PRICE_CONFIGURATION_INVALID","The configured total exceeds the supported payment range. Ask an operator to review the test offer.");
  var currentFeatures=entitlements.evaluate(w).stream().filter(Entitlements.Decision::eligible).map(Entitlements.Decision::code).collect(java.util.stream.Collectors.toSet());
  var features=entitlements.preview(w,o.targetVersionId()).stream().filter(Entitlements.Decision::eligible).filter(d->!currentFeatures.contains(d.code())).map(Entitlements.Decision::label).toList();
  var q=new Quote(UUID.randomUUID(),offerId,o.targetVersionId(),version,policy,fingerprint(w,o.targetVersionId()),(String)s.get("display_name"),o.name(),o.rentableLimit(),o.managerLimit(),features,base.toPlainString(),credit.toPlainString(),taxable.toPlainString(),o.taxRate(),tax.toPlainString(),taxable.add(tax).toPlainString(),"INR",o.intervalMonths(),o.proration(),o.recipient(),"Immediately after verified sandbox settlement; billing period begins at activation. No automatic renewal collection.",now,now.plusSeconds(600),"sandbox");db.sql("INSERT INTO subscription_upgrade_quote(id,workspace_id,actor_id,offer_id,subscription_version,expires_at,snapshot) VALUES(:id,:w,:a,:o,:v,:expiry,CAST(:s AS jsonb))").param("id",q.id()).param("w",w).param("a",actor).param("o",offerId).param("v",version).param("expiry",java.sql.Timestamp.from(q.expiresAt())).param("s",json.writeValueAsString(q)).update();audit.record(actor,w,"subscription.upgrade_quoted",q.id());return q;});}
 private String retryPolicy(){return db.sql("SELECT version FROM subscription_retry_policy WHERE effective_at<=CURRENT_TIMESTAMP ORDER BY effective_at DESC,version DESC LIMIT 1").query(String.class).optional().orElseThrow(()->new ApiProblem(503,"PAYMENT_RETRY_POLICY_UNAVAILABLE","Reviewed local retry policy is unavailable."));}
 public Change confirm(UUID actor,UUID w,UUID key,String expected,UUID quoteId){return command(actor,w,"confirm",key,Arrays.asList(expected,quoteId),Change.class,()->{active(w);Quote q=quote(w,quoteId);var s=subscription(w);match(expected,tag(w,(Integer)s.get("version")));if((Integer)s.get("version")!=q.subscriptionVersion()||policy()!=q.policyVersion()||!fingerprint(w,q.targetVersionId()).equals(q.entitlementFingerprint())||!now().isBefore(q.expiresAt()))throw new ApiProblem(409,"APPROVAL_STALE","Quote expired or its subscription/policy changed. Request a new quote.");if(!db.sql("SELECT actor_id=:a FROM subscription_upgrade_quote WHERE id=:id").param("a",actor).param("id",quoteId).query(Boolean.class).single())throw new ApiProblem(404,"QUOTE_NOT_FOUND","Quote is unavailable.");capacity(w,offered(w,q.offerId()));if(db.sql("SELECT count(*) FROM subscription_upgrade_change WHERE quote_id=:id").param("id",quoteId).query(Long.class).single()>0)throw new ApiProblem(409,"QUOTE_ALREADY_CONFIRMED","This quote already has a change. Refresh its durable status.");if(db.sql("SELECT count(*) FROM subscription_upgrade_change WHERE workspace_id=:w AND status IN('awaiting_payment','payment_unknown','review_required')").param("w",w).query(Long.class).single()>0)throw new ApiProblem(409,"UPGRADE_PENDING","Resolve the pending upgrade before another checkout.");UUID id=UUID.randomUUID();db.sql("INSERT INTO subscription_upgrade_change(id,workspace_id,actor_id,quote_id,status,retry_policy) VALUES(:id,:w,:a,:q,'awaiting_payment',:retryPolicy)").param("id",id).param("w",w).param("a",actor).param("q",q.id()).param("retryPolicy",retryPolicy()).update();audit.record(actor,w,"subscription.upgrade_confirmed",id);return change(w,id);});}
 public Change simulate(UUID actor,UUID w,UUID id,UUID key,String expected,String outcome){return settle(actor,w,id,key,expected,outcome,null);}
 public Change activateReceived(UUID actor,UUID w,UUID id,UUID key,Instant receivedAt){var c=get(actor,w,id);if(c.settlement()==null||!c.settlement().status().equals("queued")||!c.settlement().receivedAt().equals(receivedAt))throw new ApiProblem(409,"SETTLEMENT_NOT_QUEUED","Only a durable queued receipt can activate.");return settle(actor,w,id,key,c.etag(),"paid",receivedAt);}
 private Change settle(UUID actor,UUID w,UUID id,UUID key,String expected,String outcome,Instant receivedAt){return command(actor,w,"simulate:"+id,key,Arrays.asList(expected,outcome),Change.class,()->{var c=change(w,id);match(expected,c.etag());if(c.status().equals("applied"))return c;if(receivedAt==null&&c.settlement()!=null)throw new ApiProblem(409,"PAYMENT_EVIDENCE_RECORDED","Payment receipt exists. Recover activation without another payment.");if(c.status().equals("payment_failed")){if(outcome.equals("failed"))return c;throw new ApiProblem(409,"PAYMENT_RETRY_REQUIRED","Confirm an eligible retry before recording another attempt. Unknown outcomes must be reconciled, not charged again.");}if(c.status().equals("payment_unknown")&&outcome.equals("unknown"))return c;if(!Set.of("paid","failed","unknown").contains(outcome))throw new ApiProblem(422,"INVALID_OUTCOME","Choose a sandbox payment outcome.","outcome");active(w);if(!c.status().equals("payment_unknown")&&!c.status().equals("awaiting_payment")&&db.sql("SELECT count(*) FROM subscription_upgrade_change WHERE workspace_id=:w AND id<>:id AND status IN('awaiting_payment','payment_unknown','review_required')").param("w",w).param("id",id).query(Long.class).single()>0)throw new ApiProblem(409,"UPGRADE_PENDING","Another upgrade request is pending. Resolve it before retrying this failed payment.");var q=c.quote();var s=subscription(w);if((Integer)s.get("version")!=q.subscriptionVersion())throw new ApiProblem(409,"APPROVAL_STALE","Subscription changed; reconcile this request before payment.");
  if(outcome.equals("paid")){if(!(receivedAt==null?now():receivedAt).isBefore(q.expiresAt()))throw new ApiProblem(409,"APPROVAL_STALE","The payment quote expired. Record a failed sandbox outcome and request fresh terms; no money was collected.");offered(w,q.offerId());if(policy()!=q.policyVersion()||!fingerprint(w,q.targetVersionId()).equals(q.entitlementFingerprint()))throw new ApiProblem(409,"APPROVAL_STALE","Commercial policy changed. No simulated payment was taken.");capacity(w,offered(w,q.offerId()));}
  if(receivedAt==null)db.sql("INSERT INTO subscription_sandbox_payment_event(id,workspace_id,change_id,outcome,amount,currency,purpose,attempt_number) VALUES(:id,:w,:c,:o,:amount,'INR','workspace_saas_upgrade',:attempt)").param("id",UUID.randomUUID()).param("w",w).param("c",id).param("o",outcome).param("attempt",c.retry().attemptNumber(),java.sql.Types.INTEGER).param("amount",money(q.total())).update();
  String status=outcome.equals("paid")?"applied":outcome.equals("unknown")?"payment_unknown":"payment_failed";Instant applied=null;
  if(outcome.equals("paid")){applied=now();Instant end=applied.atZone(ZoneId.of("Asia/Kolkata")).plusMonths(q.intervalMonths()).toInstant();db.sql("UPDATE workspace_subscription SET plan_version_id=:p,status='active_paid',version=version+1,period_start=:start,period_end=:end,base_amount=:amount,interval_months=:months WHERE workspace_id=:w").param("p",q.targetVersionId()).param("start",java.sql.Timestamp.from(applied)).param("end",java.sql.Timestamp.from(end)).param("amount",money(q.baseAmount())).param("months",q.intervalMonths()).param("w",w).update();for(String resource:List.of("managers","rentable_items"))db.sql("UPDATE workspace_grant SET allowance=:limit WHERE workspace_id=:w AND resource=:r").param("limit",resource.equals("managers")?q.managerLimit():q.rentableLimit()).param("w",w).param("r",resource).update();}
  db.sql("UPDATE subscription_upgrade_change SET status=:s,version=version+1,applied_at=:at,failed_at=CASE WHEN :s='payment_failed' THEN clock_timestamp() ELSE failed_at END WHERE id=:id").param("s",status).param("at",applied==null?null:OffsetDateTime.ofInstant(applied,ZoneOffset.UTC),java.sql.Types.TIMESTAMP_WITH_TIMEZONE).param("id",id).update();audit.record(actor,w,"subscription.sandbox_"+status,id);return change(w,id);});}
}
